threads_select_buyer.using:
"threads"."kind" = 'buyer' and exists (
        select 1 from "companies" c where c.id = (select public.current_company_id()) and c.type = 'buyer'
      ) and (
        "threads"."request_id" in (select id from "requests") or
        "threads"."order_id" in (select id from "orders")
      )

threads_insert_buyer_own.withCheck:
"threads"."kind" = 'buyer' and "threads"."supplier_company_id" is null and exists (
        select 1 from "companies" c where c.id = (select public.current_company_id()) and c.type = 'buyer'
      ) and (
        "threads"."request_id" in (select id from "requests") or "threads"."order_id" in (select id from "orders")
      )

estimates_select_via_request.using:
"estimates"."request_id" in (
    select id from "requests" where buyer_company_id = (select public.current_company_id())
  ) or (select public.current_role()) in ('concierge', 'admin')

